import { facts, regions, stages, classes, companions } from './content.js?v=4';
import { SAVE_KEY, freshState, mergeStates, review, checkAnswer, totals, rewardId, encounterFacts, chooseAbility, playerAttack, enemyAttack, abilities } from './engine.js?v=4';
import { WORLD, castles, loreNodes, wanderers, lakes, makeWorld, walkable, near, castleAt, findPath } from './world.js?v=4';
import { cloudAvailable, connect, sync, disconnect } from './cloud.js?v=4';
import { createForest3D } from './forest3d.js?v=4';
import { helpFor, requestHint, companionSupport, combatDifficulty } from './companion.js?v=4';

const app=document.querySelector('#app'), overlay=document.querySelector('#overlay');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=freshState(),storageWarning=false;
try {const saved=JSON.parse(localStorage.getItem(SAVE_KEY));if(saved?.version===1)state=mergeStates(state,saved);}catch{storageWarning=true;}
state.world=makeWorld(state.world);
if(!walkable(state.world.x,state.world.y))Object.assign(state.world,WORLD.spawn);
let tab='world',battle=null,user=null,filter='all',answerMode='choice',lastFocus=null;
let syncTimer,worldSaveTimer,enemyTimer,frameTime=0,route=[],routeInteraction=null,nearby=null;
let forest3D=null,threeDFailed=false,follower2d=null;
const joystick={active:false,x:0,y:0,pointer:null,cx:0,cy:0};
const held=new Set();
function resetJoystick(){joystick.active=false;joystick.pointer=null;joystick.x=0;joystick.y=0;const knob=document.querySelector('#joystick-knob');if(knob)knob.style.transform='translate(-50%,-50%)';}
function dragJoystick(e){if(!joystick.active||e.pointerId!==joystick.pointer)return;const dx=e.clientX-joystick.cx,dy=e.clientY-joystick.cy,length=Math.hypot(dx,dy),scale=Math.min(1,30/(length||1));joystick.x=length<7?0:dx*scale/30;joystick.y=length<7?0:dy*scale/30;const knob=document.querySelector('#joystick-knob');if(knob)knob.style.transform=`translate(calc(-50% + ${dx*scale}px),calc(-50% + ${dy*scale}px))`;}
const skillNames={guerrier:['Frappe d’épée','Brise-garde','Riposte protégée'],mage:['Éclair arcane','Météore','Barrière magique'],archer:['Flèche vive','Tir chargé','Tir d’esquive']};
function toast(message){const node=document.querySelector('#toast');node.textContent=message;node.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.classList.remove('show'),5500);}
function save(){if(globalThis.anatomiaRecovering)return;try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));}catch{toast('La sauvegarde locale est indisponible. Exporte ta partie depuis le grimoire.');}clearTimeout(syncTimer);syncTimer=setTimeout(()=>sync(state).catch(()=>toast('Sauvegarde locale conservée ; synchronisation à réessayer.')),400);}
function touchWorld(){state.world.updatedAt=Date.now();state.updatedAt=Date.now();if(!worldSaveTimer)worldSaveTimer=setTimeout(()=>{worldSaveTimer=null;save();},600);}
function stopWalking(){route=[];routeInteraction=null;held.clear();resetJoystick();}
function modal(html){stopWalking();lastFocus=document.activeElement;overlay.innerHTML=`<div class="veil"><section class="modal" role="dialog" aria-modal="true" aria-label="Anatomia" tabindex="-1">${html}</section></div>`;overlay.querySelector('.modal').focus();}
function closeModal(){overlay.innerHTML='';lastFocus?.focus();}
function companionSvg(kind=state.profile?.companion||'loup'){
  const body=kind==='corbeau'?`<path class="animal-wing" d="M51 48 9 21l15 43 31 6m13-23 42-26-14 43-31 6" fill="#5c718b"/><ellipse cx="60" cy="61" rx="22" ry="28" fill="#35475b"/><circle cx="65" cy="33" r="19" fill="#475d75"/><path d="m80 32 23 8-24 7" fill="#d9ba6f"/><circle cx="71" cy="30" r="3" fill="#f6dfa5"/>`:kind==='dragon'?`<path class="animal-wing" d="M48 55 8 15l2 49 35 12m28-21 39-40-2 49-35 12" fill="#9c7eb0"/><ellipse cx="60" cy="65" rx="25" ry="25" fill="#bb895f"/><path d="m42 26 1-21 13 18m18 2 9-20 1 26" fill="#e9d5a5"/><ellipse cx="63" cy="40" rx="27" ry="23" fill="#c99b6b"/><path d="m80 47 15 5-11 11-18-9" fill="#dcba83"/><circle cx="56" cy="35" r="4" fill="#302e28"/>`:`<path d="m29 39-2-30 25 20m25 9 13-29 7 40" fill="#a5c4c8"/><path d="m24 38 26-15 37 10 15 30-24 32-37-9-22-30Z" fill="#c4d8d5"/><path d="m25 43 23 20 12-4 12 4 22-21-12 34-23 17-22-17Z" fill="#edf1df"/><path d="m49 63 11-5 13 5-13 10Z" fill="#33474b"/><path d="m36 43 14 5m21 0 14-5" stroke="#5f9faa" stroke-width="5"/>`;
  return `<svg viewBox="0 0 120 104" aria-hidden="true"><ellipse cx="60" cy="98" rx="34" ry="5" fill="#061918" opacity=".3"/>${body}</svg>`;
}
function renderCompanionPanel(){
  const id=state.profile?.companion||'loup',c=companions[id];
  return `<section class="card companion-card"><div class="companion-portrait">${companionSvg(id)}</div><div><span class="eyebrow gold">TON ALLIÉ</span><h3>${c.title}</h3><p>Il te suit, explique tes erreurs et te rend 3 PV après les ripostes.</p><button class="text-button" data-action="companion-info">Ses pouvoirs →</button></div></section>`;
}
function companionQuestion(b,stage){
  const f=b.queue[b.index%b.queue.length],help=helpFor(f),waiting=Math.max(0,3-(b.index-(b.lastSpecialRound??-3)));
  return `<section class="companion-assist"><div class="companion-portrait small ${b.rephrased?'special-active':''}">${companionSvg()}</div><div class="assist-body"><strong>${companions[state.profile.companion].title}</strong>${stage>=3?'<p>Épreuve d’examen : ton compagnon te laisse répondre sans indice.</p>':`<p>Un coup de pouce ? Demande une piste ou utilise Éclaircissement.</p><div class="assist-actions"><button class="button subtle" data-action="hint" ${(b.hintLevel||0)>=2?'disabled':''}>${b.hintLevel?'Indice suivant':'Demander un indice'} · ${b.hintLevel||0}/2</button><button class="button subtle" data-action="rephrase" ${waiting||b.rephrased?'disabled':''}>✧ Éclaircissement${waiting?` · ${waiting} tour${waiting>1?'s':''}`:''}</button></div>`}${b.hintLevel?`<div class="hint-bubble" role="status">${help.slice(0,b.hintLevel).map((text,i)=>`<p><b>Piste ${i+1}.</b> ${esc(text)}</p>`).join('')}</div>`:''}${b.rephrased?`<div class="hint-bubble special-bubble" role="status"><b>Autrement dit :</b> ${esc(help[2])}</div>`:''}${b.assisted?'<p class="assisted-note">Avec aide : cette réponse servira d’entraînement. Il faudra réussir sans aide pour valider la notion.</p>':''}</div></section>`;
}
function difficultySettings(){const value=state.profile?.difficulty||'auto';modal(`<span class="eyebrow gold">À TON RYTHME</span><h1>Choisis ton défi.</h1><p>La difficulté des combats peut s’adapter à tes réponses. Les niveaux de révision restent liés à tes réussites sans aide.</p><div class="difficulty-options">${[['auto','Adaptative','Le monstre ajuste sa force selon tes réponses.'],['relaxed','Détente','Des frappes moins fortes, pour explorer tranquillement.'],['challenge','Défi','Des frappes plus fortes, pour jouer avec la garde et les pouvoirs.']].map(([id,label,desc])=>`<button class="card ${value===id?'selected':''}" data-difficulty="${id}"><strong>${label}</strong><p>${desc}</p></button>`).join('')}</div><button class="button subtle" data-action="close">Retour à l’aventure</button>`);}
function crest(){return `<svg viewBox="0 0 80 100" aria-hidden="true"><path d="M40 3 72 17 68 65 40 94 12 65 8 17Z" fill="none" stroke="currentColor" stroke-width="2"/><path d="M40 15v60M22 36l18-13 18 13-18 14Z M25 57l15 18 15-18" fill="none" stroke="currentColor" stroke-width="3"/><circle cx="40" cy="50" r="6" fill="currentColor"/></svg>`;}
function heroSvg(kind='guerrier') {const color=classes[kind].color;return `<svg viewBox="0 0 120 150" aria-hidden="true"><ellipse cx="60" cy="140" rx="35" ry="7" fill="#000" opacity=".25"/><path d="M45 52 25 128 60 119 94 130 76 52Z" fill="${color}" opacity=".6"/><path d="m40 65 8 48h25l9-48-21-17Z" fill="#596466" stroke="#d1bb8d" stroke-width="2"/><path d="m49 111-5 27h14l3-26 4 26h15l-8-27" fill="#313d41"/><circle cx="61" cy="36" r="18" fill="#cfb8a1"/><path d="M42 34q0-29 22-24 20 5 17 27L64 23 44 39" fill="#343a3b"/><path d="m35 68-11 38m61-38 11 38" stroke="#a7a29a" stroke-width="10" stroke-linecap="round"/>${kind==='mage'?'<path d="M93 132V48" stroke="#d8c093" stroke-width="5"/><path d="m93 28 10 13-10 13-10-13Z" fill="#d5c0ff"/>':kind==='archer'?'<path d="M95 49q40 40 0 80V49" fill="none" stroke="#cbb88b" stroke-width="4"/>':'<path d="M92 130V53l6-12 6 12v77Z" fill="#c6d1ce"/><path d="M85 112h25" stroke="#d9b571" stroke-width="5"/>'}</svg>`;}
function monsterSvg(boss=false){return `<svg viewBox="0 0 240 210" aria-hidden="true"><ellipse cx="120" cy="192" rx="83" ry="11" fill="#000" opacity=".3"/><path d="M64 185 53 119 73 77 58 31 98 62 120 50 142 63 188 29 169 83 188 124 175 186 148 171 120 190 91 171Z" fill="${boss?'#544459':'#455653'}" stroke="#90a29a" stroke-width="2"/><path d="m73 95 34 11-17 9Zm94 0-34 11 17 9Z" fill="${boss?'#efaa97':'#e4c27c'}"/><path d="m99 139 21 10 23-10-8 26h-28Z" fill="#172126"/><path d="M70 130 38 162 29 127 62 94m110 36 30 32 9-35-32-33" fill="#526360" stroke="#90a29a" stroke-width="2"/><path d="m80 76 19 13m61-13-19 13M111 67l9 17 9-17" stroke="#90a29a" stroke-width="3" fill="none"/></svg>`;}


function render(){
  state.world=makeWorld(state.world);
  const t=totals(state),profile=state.profile||{name:'Gardien',class:'guerrier',companion:'loup'};
  const due=facts.filter(f=>state.knowledge[f.id]?.due<=Date.now()).length;
  app.innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#" data-action="world">${crest()}<span>ANATOMIA<small>LES TERRES OUBLIÉES</small></span></a><div class="season">CHAPITRE I <span>LA FORÊT DE LA CHEVILLE</span></div><nav aria-label="Navigation principale">${[['world','◇','Explorer'],['journal','▤','Grimoire'],['hero','♙','Mon personnage']].map(([id,icon,label])=>`<button class="nav ${tab===id?'active':''}" data-tab="${id}"><span>${icon}</span>${label}${id==='journal'&&due?`<b>${due}</b>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="save-dot">Progression et position sauvegardées</div><button class="google" data-action="login"><span class="google-g">G</span>${user?'Compte connecté':'Connexion Google'}</button><p>${user?'Synchronisation activée':cloudAvailable?'Retrouve ta partie sur tes appareils.':'Synchronisation Google à configurer.'}</p><button class="text-button" data-action="help">Comment jouer ?</button></div></aside><main><header class="topbar"><div><span class="eyebrow">LES TERRES OUBLIÉES</span><span class="breadcrumb"> / ${battle?'Une rencontre dans les brumes':tab==='world'?'La forêt de la Cheville':tab==='journal'?'Le grimoire':'Le refuge'}</span></div><div class="resources"><span title="Or">◈ <b>${t.gold}</b></span><span class="level">Niv. ${t.level}</span><button class="avatar" data-tab="hero" aria-label="Mon personnage">${classes[profile.class].icon}</button></div></header><div class="page">${battle?renderBattle():tab==='journal'?renderJournal():tab==='hero'?renderHero():renderWorld()}</div><footer>Anatomia · Forêt ouverte · 36 notions de cheville · Cours, pages 3 à 14</footer></main></div>`;
  if(!battle&&tab==='world'){const viewport=document.querySelector('#forest-viewport');if(!threeDFailed){try{if(!forest3D)forest3D=createForest3D(viewport);else forest3D.attach(viewport);forest3D.render(state.world,state.profile||{class:'guerrier',companion:'loup'},0,performance.now());}catch(error){threeDFailed=true;forest3D?.dispose();forest3D=null;viewport.classList.remove('has-3d');console.warn('Affichage simplifié :',error.message);}}document.querySelector('#world-mode').textContent=forest3D?'FORÊT 3D':'EXPLORATION 2D';updateWorldView();}
  if(battle?.phase==='question')app.querySelector('#answer')?.focus();
}
function forestArtwork(){
  let trees='';
  const landmarks=[...castles,...loreNodes,...wanderers,WORLD.spawn];
  for(let i=0;i<470;i++){
    const x=48+(i*173+Math.floor(i/7)*37)%1940,y=45+(i*293+Math.floor(i/9)*51)%1340;
    if(!walkable(x,y)||landmarks.some(p=>near({x,y},p,95)))continue;
    const size=24+i%17;
    trees+=`<g transform="translate(${x} ${y})"><ellipse cy="9" rx="${size*.8}" ry="12" fill="#061510" opacity=".45"/><path d="M-4-12H4V10H-4Z" fill="#665d41"/><path d="M0-${size*2.1} ${-size}-${size*.5} ${-size*.65}-${size*.5} ${-size*1.1} 0 ${size*1.1} 0 ${size*.65}-${size*.5} ${size}-${size*.5}Z" fill="${['#234b3b','#2b5140','#315942','#254333'][i%4]}" stroke="#45674b" stroke-width="1"/><path d="M0-${size*1.9} ${-size*.5}-${size*.5} 0-${size*.7}" fill="#507155" opacity=".3"/></g>`;
  }
  return `<svg class="forest-art" viewBox="0 0 ${WORLD.width} ${WORLD.height}" aria-hidden="true"><defs><pattern id="forest-floor" width="64" height="64" patternUnits="userSpaceOnUse"><path fill="#1b342a" d="M0 0H64V64H0Z"/><path d="m5 9 4 3m24 22 3-4m16 24 5 2" stroke="#52724b" opacity=".3"/></pattern><linearGradient id="lake-water" x2="1" y2="1"><stop stop-color="#306665"/><stop offset="1" stop-color="#1e424b"/></linearGradient></defs><path fill="url(#forest-floor)" d="M0 0H2048V1440H0Z"/><path d="M160 1184 256 1120 448 1152 544 960 768 1056 928 1184 1120 1088 1248 928 1456 928 1696 800 1792 576 1664 416 1536 256 1216 320 960 352 672 416 384 288M672 416 416 736 544 960M960 352 1056 544 1344 512 1664 416" fill="none" stroke="#675e3f" stroke-width="44" stroke-linejoin="round" opacity=".55"/><path d="M160 1184 256 1120 448 1152 544 960 768 1056 928 1184 1120 1088 1248 928 1456 928 1696 800 1792 576 1664 416 1536 256 1216 320 960 352 672 416 384 288" fill="none" stroke="#958359" stroke-width="2" stroke-dasharray="4 16" opacity=".4"/>${lakes.map(l=>`<g><rect x="${l.x-14}" y="${l.y-14}" width="${l.w+28}" height="${l.h+28}" rx="30" fill="#395b42"/><rect x="${l.x}" y="${l.y}" width="${l.w}" height="${l.h}" rx="24" fill="url(#lake-water)"/><path d="M${l.x+30} ${l.y+40}h75m30 48h80m-160 65h90" stroke="#a3c5a6" stroke-width="2" opacity=".25"/></g>`).join('')}${trees}<g fill="#a6c17d" opacity=".5">${Array.from({length:65},(_,i)=>`<circle cx="${72+(i*193)%1900}" cy="${50+(i*139)%1320}" r="2"/>`).join('')}</g></svg>`;
}
function castleArt(){return `<svg viewBox="0 0 150 155" aria-hidden="true"><path d="M12 140V49h13V34h14v15h14v90m44 0V49h13V34h14v15h14v91M48 136V80h54v56" fill="#748078" stroke="#b6b295" stroke-width="2"/><path d="m15 35 18-29 18 29m48 0 18-29 18 29" fill="#3d5350" stroke="#9baf9c" stroke-width="2"/><path d="M61 140v-32q14-23 28 0v32Z" fill="#1b2928" stroke="#d0b47c" stroke-width="2"/><path d="M29 65h8v17h-8m76-17h8v17h-8" fill="#dcc58a"/><path d="M6 140h138v9H6Z" fill="#8e967e"/><path d="M75 79V40m0 0h23l-9 9 9 8H75" fill="#b99969" stroke="#cfb785"/></svg>`;}
function renderWorld(){
  const w=state.world,discovered=Object.keys(w.readings).length,due=facts.filter(f=>state.knowledge[f.id]?.due<=Date.now()).length;
  const target=loreNodes.find(n=>n.ids.some(id=>!w.readings[id]))||loreNodes[0];
  return `<section class="page-heading"><div><span class="eyebrow gold">EXPLORE · DÉCOUVRE · SOUVIENS-TOI</span><h1>La forêt de la Cheville</h1><p>Les savoirs se cachent dans les bois. Les châteaux mettent ta mémoire à l’épreuve.</p></div><button class="button subtle" data-action="atlas">◇ Carte du monde</button><button class="button subtle settings-button" data-action="difficulty">Réglages</button></section><div class="openworld-layout"><section class="forest-panel"><div class="map-caption"><span class="pill" id="world-mode">FORÊT 3D</span><span>✧ ${discovered} / 36 notions découvertes</span></div><div id="forest-viewport" class="forest-viewport" tabindex="0" role="region" aria-label="Forêt à explorer. Flèches ou ZQSD pour marcher, E pour lire. Clique ou touche le sol pour te déplacer."><div id="forest-scene" class="forest-scene" style="width:${WORLD.width}px;height:${WORLD.height}px">${forestArtwork()}<button class="world-camp world-object" data-walk="camp" style="left:${WORLD.spawn.x}px;top:${WORLD.spawn.y}px" aria-label="Rejoindre le camp"><span>♨</span><small>LE CAMP</small></button>${castles.map(c=>`<button class="world-castle world-object ${c.boss?'boss-castle':''}" data-walk="${c.id}" style="left:${c.x}px;top:${c.y}px" aria-label="Marcher vers ${c.title}">${castleArt()}<span>${c.title}</span></button>`).join('')}${loreNodes.map(n=>`<button class="world-lore world-object ${n.ids.every(id=>w.readings[id])?'read':''}" data-walk="${n.id}" style="left:${n.x}px;top:${n.y}px" aria-label="Rejoindre ${n.title}"><span>${n.id==='stele-1'?'▤':'✧'}</span><small>${n.title}</small></button>`).join('')}${wanderers.map(n=>`<button class="world-monster world-object ${(w.cooldowns[n.id]||0)>Date.now()?'resting':''}" data-walk="${n.id}" style="left:${n.x}px;top:${n.y}px" aria-label="Marcher vers ${n.title}"><span>♟</span><small>${n.title}</small></button>`).join('')}<div id="world-player" class="world-player">${heroSvg(state.profile?.class)}<small>${esc(state.profile?.name||'Gardien')}</small></div><div id="world-companion" class="world-companion-fallback">${companionSvg()}<small>${companions[state.profile?.companion||'loup'].title}</small></div><div id="walk-target" class="walk-target" hidden>◇</div></div><div class="world-hud"><span>Forêt des Sceaux</span><span id="world-coordinates"></span></div><div class="world-controls"><div id="world-joystick" class="world-joystick" role="group" aria-label="Joystick tactile"><span id="joystick-knob"></span></div><div class="dpad"><button data-move="up" aria-label="Avancer">↑</button><div><button data-move="left" aria-label="À gauche">←</button><button data-move="down" aria-label="Reculer">↓</button><button data-move="right" aria-label="À droite">→</button></div></div><button id="nearby-action" class="button primary" data-action="observe" hidden>Observer · E</button></div></div><div class="forest-instructions"><span>⌨ Flèches / ZQSD · E : observer</span><span>☝ Clique sur le sol ou un lieu pour marcher</span></div><div id="world-prompt" class="world-prompt" role="status">Approche une stèle pour découvrir les savoirs de la forêt.</div></section><aside class="quest-column">${renderCompanionPanel()}<section class="card quest-card"><span class="eyebrow gold">LE CARNET DE ROUTE</span><h2>Le savoir est au bout du sentier.</h2><p>Lis les stèles, rencontre les gardiens et continue ta balade. Les notions ne te seront pas reposées juste après leur lecture.</p><div class="quest-meta"><span>✧ Prochaine découverte</span><strong>${esc(target.title)}</strong></div><button class="button primary full" data-walk="${target.id}">Suivre le sentier →</button></section><section class="card small-card"><span class="rune">⚔</span><div><h3>Une porte, une rencontre</h3><p>Entre dans un château : le combat démarre automatiquement. Choisis une attaque ; le monstre jouera ensuite.</p></div></section><section class="card small-card"><span class="rune">◷</span><div><h3>La mémoire se travaille</h3><p>${due?`${due} notions à revoir.`:'Explore pour découvrir les premières notions.'}</p><button class="text-button" data-tab="journal">Ouvrir le grimoire →</button></div></section></aside></div><section class="progress-section"><div class="section-title"><h2>Des découvertes qui deviennent des souvenirs</h2><span>${Object.keys(state.knowledge).length} / 36 notions testées</span></div><div class="stages">${stages.map((label,i)=>`<div class="stage-card"><span class="stage-number">0${i+1}</span><div><h3>${label}</h3><p>${['Apprendre dans la forêt','Retrouver après une pause','Répondre de mémoire','Réussir sans indice'][i]}</p></div><b>${facts.filter(f=>state.knowledge[f.id]?.stage===i).length}</b></div>`).join('')}</div></section>`;
}
function updateWorldView(){
  const viewport=document.querySelector('#forest-viewport'),scene=document.querySelector('#forest-scene');if(!viewport||!scene)return;
  const w=state.world,vw=viewport.clientWidth,vh=viewport.clientHeight;
  const cx=Math.max(0,Math.min(WORLD.width-vw,w.x-vw/2)),cy=Math.max(0,Math.min(WORLD.height-vh,w.y-vh/2));
  if(!forest3D){scene.style.transform=`translate(${-cx}px,${-cy}px)`;scene.dataset.cameraX=cx;scene.dataset.cameraY=cy;const hero=document.querySelector('#world-player');hero.style.left=w.x+'px';hero.style.top=w.y+'px';}
  document.querySelector('#world-coordinates').textContent=`${Math.round(w.x/32)}, ${Math.round(w.y/32)}`;
  const target=document.querySelector('#walk-target');target.hidden=!route.length;if(route.length){target.style.left=route.at(-1).x+'px';target.style.top=route.at(-1).y+'px';}
  nearby=loreNodes.find(n=>near(w,n,65))||(near(w,WORLD.spawn,65)?{id:'camp',title:'Le camp du Passeur'}:null);
  const action=document.querySelector('#nearby-action');action.hidden=!nearby;action.textContent=nearby?`Observer · ${nearby.id==='camp'?'le camp':'E'}`:'';
  document.querySelector('#world-prompt').textContent=nearby?`${nearby.title} — appuie sur E ou sur Observer.`:route.length?'Tu suis le sentier. Une touche de déplacement permet de reprendre la main.':'Entre dans un château pour affronter son gardien. Les stèles te permettent d’apprendre en chemin.';
}
function walkTo(id){
  const object=id==='camp'?{id:'camp',...WORLD.spawn}:[...castles,...loreNodes,...wanderers].find(o=>o.id===id);
  if(!object)return;tab='world';if(!document.querySelector('#forest-viewport'))render();
  route=findPath(state.world,object);routeInteraction=loreNodes.some(n=>n.id===id)||id==='camp'?id:null;held.clear();
  if(!route.length&&near(state.world,object,65)){if(routeInteraction)observe(routeInteraction);else checkEncounters();}
  updateWorldView();
}
function observe(id=nearby?.id){
  if(id==='camp'){modal(`<span class="eyebrow gold">LE CAMP DU PASSEUR</span><h1>Apprends en chemin.</h1><p>Les stèles et les carnets contiennent de courts extraits de ton cours. Lis-les, puis poursuis ton exploration. Les châteaux te demanderont de retrouver les informations sans te les remontrer juste avant.</p><p>À pied : flèches, ZQSD ou commandes tactiles. Clique sur un point du sol pour y aller. Les lacs sont infranchissables, le chemin les contourne.</p><button class="button primary" data-action="close">Reprendre l’exploration</button>`);return;}
  const node=loreNodes.find(n=>n.id===id);if(!node||!near(state.world,node,85))return;
  const notes=node.ids.map(id=>facts.find(f=>f.id===id));
  for(const f of notes)state.world.readings[f.id]={seenAt:Date.now(),seenDistance:state.world.distance,visits:(state.world.readings[f.id]?.visits||0)+1};
  touchWorld();save();render();
  modal(`<span class="eyebrow gold">UNE DÉCOUVERTE DANS LA FORÊT</span><h1>${esc(node.title)}</h1><p class="narration">« Prends le temps de comprendre ces traces. Le reste du voyage t’aidera à les retenir. »</p><div class="field-notes">${notes.map(f=>`<article><span>✧</span><p>${esc(f.lesson)}</p><a href="assets/cours-cheville-pied.pdf#page=${f.page}" target="_blank" rel="noopener">Cours · page ${f.page} ↗</a></article>`).join('')}</div><details><summary>Observer une planche du cours</summary><img class="course-image" src="assets/cours-${regions.find(r=>r.id===node.region).diagram}.jpg" alt="Planche anatomique du cours"><p>Une illustration de contexte, à relire à ton rythme.</p></details><p class="fine-print">Ces informations ne seront pas utilisées en combat avant que tu aies parcouru au moins huit cases supplémentaires. Tu peux continuer à explorer ou découvrir un autre lieu.</p><button class="button primary" data-action="close">Poursuivre ma balade →</button>`);
}
function atlas(){modal(`<span class="eyebrow gold">LA FORÊT DES SCEAUX</span><h1>Choisis ta destination.</h1><p>Ton personnage marchera jusqu’au lieu choisi ; tu peux reprendre la main avec les flèches.</p><div class="atlas-list">${[...loreNodes,...castles].map(o=>`<button class="atlas-place" data-travel="${o.id}"><span>${o.ids?'✧':'♜'}</span><div><strong>${o.title}</strong><small>${o.ids?'Découverte dans la forêt':'Combat à l’entrée'}</small></div><b>→</b></button>`).join('')}</div><button class="button subtle" data-action="close">Revenir à la forêt</button>`);}
function checkEncounters(){
  if(battle||overlay.innerHTML||tab!=='world')return;
  const castle=castleAt(state.world);
  if(castle){begin(castle.region,castle.boss,false,castle);return;}
  const monster=wanderers.find(n=>near(state.world,n,38)&&(state.world.cooldowns[n.id]||0)<=Date.now());
  if(monster){state.world.cooldowns[monster.id]=Date.now()+120000;begin(monster.region,false,false,monster);}
}
function advanceWorld(dx,dy){
  const w=state.world,old={x:w.x,y:w.y};
  if(walkable(w.x+dx,w.y))w.x+=dx;if(walkable(w.x,w.y+dy))w.y+=dy;
  const travelled=Math.hypot(w.x-old.x,w.y-old.y);if(travelled){w.distance+=travelled;touchWorld();updateWorldView();checkEncounters();}
}
function frame(now){
  const dt=Math.min(.05,(now-frameTime)/1000||0);frameTime=now;
  if(tab==='world'&&!battle&&!overlay.innerHTML&&state.profile){
    let dx=joystick.active?joystick.x:Number(held.has('right'))-Number(held.has('left')),dy=joystick.active?joystick.y:Number(held.has('down'))-Number(held.has('up'));
    if(dx||dy){const length=Math.hypot(dx,dy),power=Math.min(1,length);advanceWorld(dx/length*WORLD.speed*dt*power,dy/length*WORLD.speed*dt*power);}
    else if(route.length){const next=route[0],distance=Math.hypot(next.x-state.world.x,next.y-state.world.y),step=WORLD.speed*dt;
      if(distance<=step+1){advanceWorld(next.x-state.world.x,next.y-state.world.y);route.shift();if(!route.length&&routeInteraction&&!battle){const id=routeInteraction;routeInteraction=null;observe(id);}}
      else advanceWorld((next.x-state.world.x)/distance*step,(next.y-state.world.y)/distance*step);
    }
  }
  if(tab==='world'&&!battle&&state.profile){if(forest3D)forest3D.render(state.world,state.profile,dt,now,route.at(-1));else{const node=document.querySelector('#world-companion');if(node){if(!follower2d||Math.hypot(follower2d.x-state.world.x,follower2d.y-state.world.y)>300)follower2d={x:state.world.x-38,y:state.world.y+30};const alpha=1-Math.exp(-dt*4);follower2d.x+=(state.world.x-38-follower2d.x)*alpha;follower2d.y+=(state.world.y+30-follower2d.y)*alpha;node.style.left=follower2d.x+'px';node.style.top=follower2d.y+'px';}}}
  requestAnimationFrame(frame);
}

function renderJournal(){
  const list=facts.filter(f=>filter==='all'||filter==='new'&&!state.knowledge[f.id]||filter==='due'&&state.knowledge[f.id]?.due<=Date.now()||filter===String(state.knowledge[f.id]?.stage));
  return `<section class="page-heading"><div><span class="eyebrow gold">TES CONNAISSANCES, PAS À PAS</span><h1>Le grimoire du Gardien</h1><p>Chaque notion possède sa propre progression et sa prochaine révision.</p></div><button class="button subtle" data-action="export">Exporter ma partie</button></section><div class="notice">Ce premier territoire couvre 36 notions textuelles de l’articulation talo-crurale. Les schémas sont consultables ; leurs repères visuels ne sont pas encore tous évalués. Les huit autres PDF et la partie pied seront ajoutés ensuite.</div><div class="filter-row">${[['all','Tout'],['new','À découvrir'],['due','À revoir'],...stages.map((s,i)=>[String(i),s])].map(([id,label])=>`<button class="chip ${filter===id?'selected':''}" data-filter="${id}">${label}</button>`).join('')}<button class="chip" data-action="errors">Revoir mes erreurs</button></div><div class="knowledge-list">${list.length?list.map(f=>{const k=state.knowledge[f.id];return `<article class="knowledge-card"><div><span class="eyebrow">${esc(regions.find(r=>r.id===f.region).subtitle)} · P. ${f.page}</span><h3>${esc(f.question)}</h3><details><summary>Voir la réponse du cours</summary><p>${esc(f.answer)}</p><a href="assets/cours-cheville-pied.pdf#page=${f.page}" target="_blank" rel="noopener">Vérifier dans le PDF ↗</a></details></div><div class="knowledge-status"><span class="pill">${k?stages[k.stage]:'À découvrir'}</span><small>${k?`${k.correct}/${k.attempts} réponses justes sans aide`:'Pas encore étudiée'}</small>${k?.practiceAttempts?`<small>${k.practiceAttempts} entraînement${k.practiceAttempts>1?'s':''} avec aide</small>`:''}<small>${k?(k.due<=Date.now()?'À revoir maintenant':`Prochaine révision : ${new Date(k.due).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'})}`):''}</small>${k?.mastered?'<span class="gold">✦ Examen validé</span>':''}</div></article>`;}).join(''):'<div class="card empty">Aucune notion dans cette catégorie pour le moment.</div>'}</div><button class="button subtle" data-action="import">Importer une sauvegarde</button><input id="import-file" type="file" accept="application/json" hidden>`;
}
function renderHero(){const p=state.profile, t=totals(state);if(!p)return '';const gear=[['Cape des brumes',0,'Une cape pour commencer ton voyage.'],['Lame du veilleur',2,'+2 dégâts sur une bonne réponse.'],['Armure des sceaux',5,'Réduit de 2 les dégâts reçus.'],['Couronne du savoir',10,'Un trophée pour tes victoires.']];return `<section class="page-heading"><div><span class="eyebrow gold">LE REFUGE DES GARDIENS</span><h1>${esc(p.name)}</h1><p>Niveau ${t.level} · ${t.xp} XP · ${t.wins} victoires</p></div><button class="button subtle" data-action="customize">Personnaliser</button></section><div class="hero-layout"><section class="card portrait">${heroSvg(p.class)}<h2>${classes[p.class].title}</h2><div class="xp-track"><i style="width:${t.xp%100}%"></i></div><p>${t.xp%100} / 100 XP vers le prochain niveau</p><div class="companion-badge"><div class="companion-portrait">${companionSvg(p.companion)}</div>${companions[p.companion].title}<button class="text-button" data-action="customize">Changer de compagnon →</button></div></section><div><h2>Ta classe</h2><p class="muted">Change librement en dehors des combats. Tes connaissances restent acquises.</p><div class="class-grid">${Object.entries(classes).map(([id,c])=>`<button class="card class-card ${p.class===id?'selected':''}" data-class="${id}"><span>${c.icon}</span><h3>${c.title}</h3><p>${c.desc}</p><small>${p.class===id?'Classe équipée':'Essayer cette classe'}</small></button>`).join('')}</div><h2>Ton équipement</h2><div class="gear-grid">${gear.map(([name,needed,desc])=>`<div class="card gear ${t.wins>=needed?'':'locked'}"><span>${t.wins>=needed?'✦':'◇'}</span><h3>${name}</h3><p>${desc}</p><small>${t.wins>=needed?'Débloqué et équipé':`${needed} victoires nécessaires`}</small></div>`).join('')}</div><p class="fine-print">L’or est conservé pour une future boutique. Pour ce prototype, l’équipement se débloque avec les victoires.</p></div></div>`;}


function begin(region,boss=false,errors=false,origin=null){
  if(!state.profile){setup();return;}
  const queue=encounterFacts(facts,state,{region,boss,errors});
  if(!queue.length){toast(errors?'Explore encore un peu avant de retravailler ces erreurs.':'Ces notions viennent d’être lues. Poursuis ta promenade avant cette rencontre.');if(origin?.id)Object.assign(state.world,{x:origin.x,y:origin.y+110});stopWalking();updateWorldView();return;}
  stopWalking();clearTimeout(enemyTimer);tab='world';
  battle={id:rewardId(),region,queue,index:0,hp:100,enemy:boss?190:96,maxEnemy:boss?190:96,energy:3,streak:0,correct:0,phase:'choose',ability:null,boss,origin,results:[],log:['Le gardien s’approche. À toi de choisir une attaque.'],maxTurns:boss?12:8,finished:false,feedback:null};
  prepareQuestion();save();render();
}
function prepareQuestion(){const b=battle;b.assisted=false;b.hintLevel=0;b.rephrased=false;b.draftAnswer='';b.companionHealing=0;const f=b.queue[b.index%b.queue.length],attempt=state.knowledge[f.id]?.attempts||0;const variants=f.questions||[f.question];b.prompt=variants[(attempt+b.index)%variants.length];b.options=[...f.choices];for(let i=b.options.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b.options[i],b.options[j]]=[b.options[j],b.options[i]];}}
function renderBattle(){
  const b=battle;if(b.finished)return renderResult();
  const f=b.queue[b.index%b.queue.length],stage=b.boss?3:state.knowledge[f.id]?.stage||0;
  const names=skillNames[state.profile.class],monster=wanderers.some(n=>n.id===b.origin?.id)?b.origin.title:(b.boss?'Le Gardien de la Mortaise':regions.find(r=>r.id===f.region).monster);
  const written=stage>=2||answerMode==='written';
  const intent=['une frappe directe','une attaque lourde','une morsure rapide'][b.index%3];
  const phaseLabel={choose:'À TOI DE JOUER',question:'PRÉPARE TON ATTAQUE','player-result':'TON ATTAQUE', 'enemy-turn':'TOUR DU MONSTRE',resolved:'LE MONSTRE A JOUÉ',victory:'LE MONSTRE EST VAINCU',defeat:'TON HÉROS EST À TERRE'}[b.phase];
  let body='';
  if(b.phase==='choose')body=`<span class="eyebrow gold">CHOISIS TON ACTION</span><h2>Le monstre prépare ${intent}.</h2><p class="muted">Choisis une attaque, puis retrouve une notion de mémoire pour la réussir. S’il survit, le monstre ripostera.</p><div class="skill-grid">${Object.entries(abilities).map(([id,a],i)=>`<button class="skill-button ${id==='power'?'power-skill':''}" data-ability="${id}" ${b.energy<a.cost?'disabled':''}><span>${['⚔','✦','◈'][i]}</span><strong>${names[i]}</strong><p>${a.desc}</p><small>${a.cost?`${a.cost} concentration`:'Sans coût'}</small></button>`).join('')}</div>`;
  else if(b.phase==='question')body=`<div class="question-meta"><span class="eyebrow gold">${esc(names[Object.keys(abilities).indexOf(b.ability)])} · ${stages[stage]}</span><span>Rappel de mémoire</span></div><h2>${esc(b.prompt)}</h2>${stage<2?`<div class="mode-toggle"><button class="chip ${!written?'selected':''}" data-mode="choice">Choix proposés</button><button class="chip ${written?'selected':''}" data-mode="written">Réponse de mémoire</button></div>`:'<p class="fine-print">Sans propositions. Les accents, la casse et les tirets ne sont pas exigés.</p>'}${written?`<form id="answer-form"><label for="answer">Ta réponse</label><div class="answer-input"><input id="answer" name="answer" value="${esc(b.draftAnswer||'')}" required autocomplete="off" placeholder="Retrouve les termes du cours…"><button class="button primary" type="submit">Lancer l’attaque →</button></div></form>`:`<div class="answers">${b.options.map((choice,i)=>`<button class="answer" data-answer="${esc(choice)}"><span>${String.fromCharCode(65+i)}</span>${esc(choice)}</button>`).join('')}</div>`}`;
  else body=`<div class="feedback ${b.feedback?.correct?'correct':'incorrect'}"><strong>${b.feedback?.correct?'✦ Attaque réussie !':'Ton attaque manque sa cible.'}</strong><p>${esc(f.answer)}</p><p>${esc(b.feedback?.message||'')}</p><a href="assets/cours-cheville-pied.pdf#page=${f.page}" target="_blank" rel="noopener">Vérifier dans le cours · page ${f.page} ↗</a></div>${b.phase==='player-result'?'<p class="turn-wait" role="status">Le monstre prend son tour…</p>':b.phase==='enemy-turn'?'<p class="turn-wait" role="status">Le monstre attaque !</p>':`<div class="enemy-report" role="status">${b.phase==='victory'?'Le gardien est vaincu avant sa riposte.':`Le monstre t’a infligé ${b.incoming} dégâts.${b.protected?' Ton compagnon t’a protégé du dernier coup.':''}`}</div><button class="button primary" data-action="next">${['victory','defeat'].includes(b.phase)||b.index+1>=b.maxTurns?'Voir le bilan':'Choisir ma prochaine attaque'} →</button>`}`;
  return `<div class="battle-heading"><button class="text-button" data-action="abandon">← Revenir à la forêt</button><span class="pill">${b.boss?'BOSS · ':''}TOUR ${b.index+1} / ${b.maxTurns}</span></div><section class="arena phase-${b.phase}"><div class="combatant hero-combatant"><div class="fighter-art">${heroSvg(state.profile.class)}</div><strong>${esc(state.profile.name)}</strong><div class="health"><i style="width:${b.hp}%"></i></div><small>${b.hp} / 100 PV · ${classes[state.profile.class].title}</small></div><div class="versus">⚔<small>${phaseLabel}</small><span class="energy">${'◆'.repeat(b.energy)}${'◇'.repeat(3-b.energy)}</span></div><div class="combatant enemy"><div class="fighter-art monster">${monsterSvg(b.boss)}</div><strong>${esc(monster)}</strong><div class="health"><i style="width:${b.enemy/b.maxEnemy*100}%"></i></div><small>${b.enemy} / ${b.maxEnemy} PV</small></div></section><section class="question-card card">${body}</section>${b.phase==='question'?companionQuestion(b,stage):`<section class="companion-assist ${b.phase==='resolved'&&b.companionHealing?'companion-healing':''}"><div class="companion-portrait small">${companionSvg()}</div><div class="assist-body"><strong>${companions[state.profile.companion].title}</strong>${b.feedback&&!b.feedback.correct?`<p class="companion-explanation">Dans ton cours : ${esc(f.lesson)}</p><p>Compare cette information à ta réponse. On la retravaillera sans aide.</p>`:b.companionHealing?`<p>Je veille sur toi : +${b.companionHealing} PV après la riposte.</p>`:'<p>Je reste à tes côtés. Tu pourras me demander un indice pendant ta prochaine question.</p>'}${b.assisted?'<p class="assisted-note">Réponse aidée : entraînement uniquement, sans validation de maîtrise.</p>':''}</div></section>`}<div class="combat-log" aria-label="Journal du combat">${b.log.slice(-4).map(line=>`<p>${esc(line)}</p>`).join('')}</div>${stage===0?'<p class="fine-print">Apprentissage : le monstre attaque à chaque tour, mais ton compagnon t’empêche de tomber à zéro PV.</p>':''}`;
}
function submit(value){
  if(!battle||battle.phase!=='question')return;
  const b=battle,f=b.queue[b.index%b.queue.length],stage=b.boss?3:state.knowledge[f.id]?.stage||0;
  const correct=checkAnswer(f,value);state.knowledge[f.id]=review(state.knowledge[f.id],correct,Date.now(),{assisted:b.assisted});
  const result=playerAttack(b,correct,classes[state.profile.class],totals(state).wins);Object.assign(b,result);
  b.correct+=Number(correct);b.learning=stage===0;
  b.feedback={correct,message:correct?`${b.damage} dégâts infligés.${b.phase==='victory'?' Le monstre est vaincu.':''}`:'Relis la correction. Tu retrouveras cette notion dans une prochaine révision.'};
  b.results.push({id:f.id,prompt:b.prompt,correct,given:value,assisted:Boolean(b.assisted)});b.log.push(`Toi · ${correct?`${b.damage} dégâts infligés`:'attaque manquée'}.`);
  state.updatedAt=Date.now();save();render();
  if(b.phase!=='victory')enemyTimer=setTimeout(()=>{
    if(battle?.id!==b.id||battle.phase!=='player-result')return;b.phase='enemy-turn';render();
    enemyTimer=setTimeout(()=>{if(battle?.id!==b.id||battle.phase!=='enemy-turn')return;Object.assign(b,enemyAttack(b,classes[state.profile.class],{learning:b.learning,wins:totals(state).wins,damageScale:combatDifficulty(state)}));b.log.push(`Monstre · t’inflige ${b.incoming} dégâts${b.ability==='guard'?' (garde active)':''}.`);Object.assign(b,companionSupport(b));if(b.companionHealing)b.log.push(`${companions[state.profile.companion].title} · te rend ${b.companionHealing} PV.`);render();},650);
  },1000);
}
function next(){
  if(!battle||!['resolved','victory','defeat'].includes(battle.phase))return;
  if(['victory','defeat'].includes(battle.phase)||battle.index+1>=battle.maxTurns){finish();return;}
  battle.index++;battle.phase='choose';battle.feedback=null;battle.ability=null;prepareQuestion();render();
}
function finish(){
  const b=battle;if(b.finished)return;b.finished=true;b.win=b.enemy<=0&&b.hp>0;
  state.rewards[b.id]={xp:b.results.reduce((total,r)=>total+(r.correct?(r.assisted?5:10):0),0)+(b.win?20:0),gold:b.win?15:3,win:b.win,at:Date.now()};state.updatedAt=Date.now();save();render();
}
function returnToForest(){
  clearTimeout(enemyTimer);stopWalking();if(battle?.origin){Object.assign(state.world,{x:battle.origin.x,y:Math.min(WORLD.height-40,battle.origin.y+120)});}
  battle=null;tab='world';touchWorld();save();render();
}
function renderResult(){const b=battle,r=state.rewards[b.id];return `<section class="result card"><div class="result-rune">${b.win?'✦':'◇'}</div><span class="eyebrow gold">LA RENCONTRE S’ACHÈVE</span><h1>${b.win?'Le gardien est vaincu.':b.hp<=0?'Le Passeur te ramène à l’abri.':'Le gardien se retire dans les brumes.'}</h1><p>${b.correct} / ${b.results.length} réponses justes · ${b.hp} PV restants</p><div class="rewards"><span>+${r.xp} XP</span><span>+${r.gold} or</span></div><p class="fine-print">La victoire dépend des PV du monstre : chaque attaque compte. Les notions gardent leur progression propre ; une victoire ne valide pas automatiquement un niveau examen.</p><div class="result-list">${b.results.map(result=>{const f=facts.find(f=>f.id===result.id);return `<details><summary>${result.correct?'✓':'↻'} ${esc(result.prompt)}</summary><p>Ta réponse : ${esc(result.given)}</p><p>Réponse du cours : ${esc(f.answer)}</p>${result.assisted?'<p class="assisted-note">Avec aide · entraînement uniquement</p>':''}<a href="assets/cours-cheville-pied.pdf#page=${f.page}" target="_blank" rel="noopener">Source · page ${f.page}</a></details>`;}).join('')}</div><div class="button-row">${!b.win?'<button class="button primary" data-action="retry-battle">Réessayer</button><button class="button subtle" data-action="review-mistakes">Revoir mes erreurs</button>':''}<button class="button primary" data-action="finish">Reprendre ma balade →</button></div></section>`;}

function setup(customize=false){
  const p=state.profile||{name:'',class:'guerrier',companion:'loup'};
  modal(`<div class="modal-crest">${crest()}</div><span class="eyebrow gold">BIENVENUE DANS ANATOMIA</span><h1>${customize?'Ton identité de Gardien':'Les Terres oubliées t’attendent.'}</h1><p>Parcours la forêt de la Cheville, découvre ses savoirs et affronte les gardiens des châteaux.</p><form id="profile-form"><label for="hero-name">Le nom de ton héros</label><input id="hero-name" name="name" required maxlength="24" value="${esc(p.name)}" placeholder="Choisis ton nom…"><label for="hero-class">Essaie une première classe — tu pourras changer</label><select name="class" id="hero-class">${Object.entries(classes).map(([id,c])=>`<option value="${id}" ${p.class===id?'selected':''}>${c.title} · ${c.desc}</option>`).join('')}</select><label>Choisis ton premier compagnon</label><div class="companion-options">${Object.entries(companions).map(([id,c])=>`<label class="companion-option"><input type="radio" name="companion" value="${id}" ${p.companion===id?'checked':''}><span class="companion-portrait">${companionSvg(id)}</span><strong>${c.title}</strong><small>${c.desc}</small></label>`).join('')}</div><button class="button primary full" type="submit">${customize?'Enregistrer':'Entrer dans l’aventure'} →</button></form><p class="fine-print">Première version : sauvegarde locale immédiate. ${cloudAvailable?'Connexion Google disponible dans le menu.':'La synchronisation Google attend sa configuration.'}</p>${customize?'<button class="text-button" data-action="close">Annuler</button>':''}`);
}

function help(){modal(`<span class="eyebrow gold">L’AVENTURE DANS LA FORÊT</span><h1>Explore avant de combattre.</h1><ol class="help-list"><li><strong>Marche librement</strong> avec les flèches, ZQSD, les boutons tactiles ou un clic sur le sol. Le chemin contourne les lacs.</li><li><strong>Observe les stèles</strong> en t’approchant puis en appuyant sur E. Elles expliquent quelques informations, sans te poser la future question.</li><li><strong>Continue ton voyage</strong> : une notion lue est écartée des combats pendant les huit cases suivantes.</li><li><strong>Entre dans un château</strong> : le combat commence automatiquement. Choisis une frappe rapide, une attaque puissante ou une garde, puis réponds. Si le monstre survit, il attaque à son tour, même après une bonne réponse.</li></ol><p>La concentration sert aux attaques puissantes. Les frappes simples réussies la restaurent. En apprentissage, ton compagnon t’empêche de tomber à zéro PV.</p><p>Les niveaux des notions avancent grâce aux révisions espacées : 10 minutes, puis un jour, trois jours et sept jours. Une erreur rapproche le prochain rappel.</p><button class="button primary" data-action="close">Partir explorer</button>`);}
async function login(){if(user){modal(`<h1>Compte Google connecté</h1><p>La synchronisation est active. La sauvegarde locale reste disponible.</p><button class="button subtle" data-action="logout">Se déconnecter</button><button class="button primary" data-action="close">Fermer</button>`);return;}if(!cloudAvailable){modal(`<span class="eyebrow gold">SAUVEGARDE MULTIAPPAREIL</span><h1>Connexion Google à activer</h1><p>Le prototype conserve déjà ta partie sur cet appareil. Pour la retrouver automatiquement ailleurs, le service Google et sa base de données doivent être configurés.</p><p>En attendant, tu peux exporter et importer ta partie depuis le grimoire.</p><button class="button primary" data-action="close">Continuer ma partie locale</button>`);return;}try{user=await connect(()=>state,incoming=>{state=incoming;try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));}catch{}if(!battle)render();},toast);toast('Connexion Google et synchronisation activées.');render();if(!state.profile)setup();}catch(e){toast(e.code==='auth/popup-closed-by-user'?'Connexion annulée. Ta sauvegarde locale est conservée.':'Connexion indisponible. Vérifie le réseau et la configuration Google.');}}


function requestTab(id){if(battle){modal(`<h2>Quitter cette rencontre ?</h2><p>Les réponses sont conservées. Les récompenses sont attribuées à la fin du combat.</p><button class="button subtle" data-leave-tab="${id}">Quitter</button><button class="button primary" data-action="close">Continuer</button>`);return;}stopWalking();tab=id;render();}
function handleClick(e){
  const el=e.target.closest('button,[data-action]');if(!el)return;
  if(el.dataset.leaveTab){const dest=el.dataset.leaveTab;closeModal();returnToForest();tab=dest;render();return;}
  if(el.dataset.tab){requestTab(el.dataset.tab);return;}
  if(el.dataset.travel){const id=el.dataset.travel;closeModal();walkTo(id);return;}
  if(el.dataset.walk){if(!battle)walkTo(el.dataset.walk);return;}
  if(el.dataset.move){if(e.detail===0){route=[];advanceWorld(...({up:[0,-32],down:[0,32],left:[-32,0],right:[32,0]}[el.dataset.move]));}return;}
  if(el.dataset.difficulty){state.profile.difficulty=el.dataset.difficulty;state.profileUpdatedAt=state.updatedAt=Date.now();save();closeModal();render();return;}
  if(el.dataset.filter){filter=el.dataset.filter;render();return;}
  if(el.dataset.mode){answerMode=el.dataset.mode;render();return;}
  if(el.dataset.ability){if(!battle)return;const selected=chooseAbility(battle,el.dataset.ability);if(selected!==battle){battle=selected;render();}return;}
  if(el.dataset.answer!==undefined){submit(el.dataset.answer);return;}
  if(el.dataset.class){state.profile.class=el.dataset.class;state.profileUpdatedAt=state.updatedAt=Date.now();save();render();toast(`Classe ${classes[el.dataset.class].title} équipée.`);return;}
  const action=el.dataset.action;
  if(action==='world'){e.preventDefault();requestTab('world');}
  else if(action==='login'){if(battle){toast('Termine ou quitte le combat avant de changer de compte.');return;}login();}
  else if(action==='logout')sync(state).then(()=>disconnect()).then(()=>{user=null;state=freshState();state.world=makeWorld();save();closeModal();render();setup();}).catch(()=>toast('Synchronisation interrompue. Réessaie avant de te déconnecter.'));
  else if(action==='close')closeModal();
  else if(action==='help')help();
  else if(action==='customize')setup(true);
  else if(action==='atlas')atlas();
  else if(action==='difficulty')difficultySettings();
  else if(action==='hint'||action==='rephrase'){if(!battle)return;const f=battle.queue[battle.index%battle.queue.length],stage=battle.boss?3:state.knowledge[f.id]?.stage||0;battle=requestHint(battle,stage,{special:action==='rephrase'});render();}
  else if(action==='companion-info')modal(`<span class="eyebrow gold">TON COMPAGNON DE ROUTE</span><h1>${companions[state.profile.companion].title}</h1><div class="companion-portrait large">${companionSvg()}</div><p>Il marche ou vole à tes côtés et te rend automatiquement 3 PV après chaque riposte, si ton héros est encore debout.</p><p>En combat, demande jusqu’à deux indices progressifs. Éclaircissement reformule la question sans donner sa réponse et revient tous les trois tours.</p><p>Une réponse obtenue avec aide sert d’entraînement. Les épreuves d’examen restent sans indice.</p><button class="button primary" data-action="close">Repartir ensemble</button>`);
  else if(action==='observe')observe();
  else if(action==='course')window.open('assets/cours-cheville-pied.pdf','_blank','noopener');
  else if(action==='errors')begin(undefined,false,true);
  else if(action==='next')next();
  else if(action==='finish')returnToForest();
  else if(action==='retry-battle'){const {region,boss,origin}=battle;begin(region,boss,false,origin);}
  else if(action==='review-mistakes'){const errors=battle.results.filter(r=>!r.correct);modal(`<h1>Comprendre mes erreurs</h1><div class="field-notes">${errors.length?errors.map(r=>{const f=facts.find(f=>f.id===r.id);return `<article><p>${esc(f.lesson)}</p><a href="assets/cours-cheville-pied.pdf#page=${f.page}" target="_blank" rel="noopener">Page ${f.page} ↗</a></article>`;}).join(''):'<p>Aucune erreur dans cette rencontre.</p>'}</div><button class="button primary" data-action="close">Revenir au bilan</button>`);}
  else if(action==='abandon')modal('<h2>Revenir dans la forêt ?</h2><p>Tes réponses sont enregistrées, mais cette rencontre ne donnera pas de récompense de fin.</p><button class="button subtle" data-action="confirm-abandon">Revenir dans la forêt</button><button class="button primary" data-action="close">Continuer le combat</button>');
  else if(action==='confirm-abandon'){closeModal();returnToForest();}
  else if(action==='export'){try{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='anatomia-sauvegarde.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch{toast('L’export est indisponible dans ce navigateur. Ta partie reste sauvegardée localement.');}}
  else if(action==='import')document.querySelector('#import-file').click();
}
document.addEventListener('click',handleClick);
document.addEventListener('input',e=>{if(e.target.id==='answer'&&battle?.phase==='question')battle.draftAnswer=e.target.value;});
document.addEventListener('submit',e=>{
  if(e.target.id==='answer-form'){e.preventDefault();submit(new FormData(e.target).get('answer'));}
  if(e.target.id==='profile-form'){e.preventDefault();const form=new FormData(e.target),name=String(form.get('name')).trim();if(!name)return;state.profile={...state.profile,name,class:form.get('class'),companion:form.get('companion')};state.profileUpdatedAt=state.updatedAt=Date.now();save();closeModal();render();}
});
document.addEventListener('change',async e=>{if(e.target.id!=='import-file'||!e.target.files[0])return;try{const incoming=JSON.parse(await e.target.files[0].text());if(incoming.version!==1||!incoming.profile||!classes[incoming.profile.class]||!companions[incoming.profile.companion]||typeof incoming.profile.name!=='string'||!incoming.knowledge||!incoming.rewards)throw Error();for(const [id,k] of Object.entries(incoming.knowledge))if(!facts.some(f=>f.id===id)||!Number.isInteger(k.stage)||k.stage<0||k.stage>3||![k.attempts,k.correct,k.due,k.updatedAt].every(Number.isFinite))throw Error();for(const r of Object.values(incoming.rewards))if(![r.xp,r.gold,r.at].every(n=>Number.isFinite(n)&&n>=0))throw Error();if(incoming.world&&(![incoming.world.x,incoming.world.y,incoming.world.distance].every(Number.isFinite)||incoming.world.distance<0||!walkable(incoming.world.x,incoming.world.y)))throw Error();if(incoming.world)for(const [id,r] of Object.entries(incoming.world.readings||{}))if(!facts.some(f=>f.id===id)||![r.seenAt,r.seenDistance,r.visits].every(Number.isFinite))throw Error();state=mergeStates(state,incoming);state.world=makeWorld(state.world);save();render();toast('Sauvegarde importée.');}catch{toast('Fichier invalide. Ta partie actuelle est conservée.');}});
const directionFor=key=>({ArrowUp:'up',z:'up',w:'up',ArrowDown:'down',s:'down',ArrowLeft:'left',q:'left',a:'left',ArrowRight:'right',d:'right'})[key];
document.addEventListener('keydown',e=>{
  if(overlay.innerHTML){if(e.key==='Escape'&&state.profile){closeModal();return;}if(e.key==='Tab'){const nodes=[...overlay.querySelectorAll('button,input,select,a[href]')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement.classList.contains('modal'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}return;}
  if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;
  if(tab!=='world'||battle)return;
  const direction=directionFor(e.key);if(direction){e.preventDefault();resetJoystick();route=[];routeInteraction=null;held.add(direction);}
  if(e.key.toLowerCase()==='e'){e.preventDefault();observe();}
});
document.addEventListener('keyup',e=>held.delete(directionFor(e.key)));
document.addEventListener('pointerdown',e=>{
  const stick=e.target.closest('#world-joystick');
  if(stick&&!battle&&tab==='world'&&!overlay.innerHTML){e.preventDefault();const rect=stick.getBoundingClientRect();stopWalking();joystick.active=true;joystick.pointer=e.pointerId;joystick.cx=rect.left+rect.width/2;joystick.cy=rect.top+rect.height/2;stick.setPointerCapture?.(e.pointerId);dragJoystick(e);return;}
  const control=e.target.closest('[data-move]');
  if(control&&!battle&&tab==='world'){e.preventDefault();control.setPointerCapture?.(e.pointerId);held.add(control.dataset.move);route=[];routeInteraction=null;return;}
  const viewport=e.target.closest('#forest-viewport');if(!viewport||e.target.closest('button')||battle||overlay.innerHTML)return;
  const rect=viewport.getBoundingClientRect(),scene=document.querySelector('#forest-scene');
  const destination=forest3D?forest3D.screenToWorld(e.clientX,e.clientY):{x:e.clientX-rect.left+Number(scene.dataset.cameraX),y:e.clientY-rect.top+Number(scene.dataset.cameraY)};if(!destination)return;
  route=findPath(state.world,destination);routeInteraction=null;held.clear();updateWorldView();
});
document.addEventListener('pointermove',e=>{if(joystick.active){e.preventDefault();dragJoystick(e);}},{passive:false});
document.addEventListener('pointerup',()=>{held.clear();resetJoystick();});
document.addEventListener('pointercancel',()=>{held.clear();resetJoystick();});
window.addEventListener('blur',()=>{held.clear();resetJoystick();});
window.addEventListener('resize',()=>{if(tab==='world'&&!battle)updateWorldView();});
document.addEventListener('visibilitychange',()=>{held.clear();resetJoystick();if(document.hidden)save();});
window.addEventListener('storage',e=>{if(e.key===SAVE_KEY){try{state=mergeStates(state,JSON.parse(e.newValue));if(!battle)render();}catch{}}});
render();if(!state.profile)setup();if(storageWarning)toast('La sauvegarde précédente ne pouvait pas être lue.');requestAnimationFrame(frame);
